contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address u) public payable {
        uint first;
        bool reverted1;
        uint256 v1 = c.getBalance(u); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            first = 0;
            reverted1 = true;
        } else {
            first = v1;
            reverted1 = false;
        }

        uint second;
        bool reverted2;
        uint256 v2 = c.getBalance(u); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            second = 0;
            reverted2 = true;
        } else {
            second = v2;
            reverted2 = false;
        }

        assert(reverted1 == reverted2 && (!reverted1 || first == second));
    }

    receive() external payable {}
}

